document.addEventListener('DOMContentLoaded', function () {
    // ****** Nav Mobile
    function openBurger() {
        var MobNav = $('.navbar-toggler');
        MobNav.on('click', function () {
            $('.navbar-toggler .btn-menu').toggleClass('d-none');
            $('.nav-mobile').toggleClass('nav-mobile-active');
            $('.first-nav').toggleClass('first-nav-active');
        });
    }

    // ****** Curseur musique
    function cursorMusic() {
        const musicCursor = document.querySelector(".cursor-follow-music");

        let lastX = 0;
        let lastY = 0;

        document.addEventListener("mousemove", (e) => {

        const dx = e.clientX - lastX;
        const dy = e.clientY - lastY;

        const distance = Math.sqrt(dx * dx + dy * dy);

        // seuil minimum de mouvement pour créer une note
        if(distance > 10){

            const note = document.createElement("div");
            note.classList.add("music-note");

            const notes = ["♪","♫","♩","♬"];
            note.textContent = notes[Math.floor(Math.random() * notes.length)];

            note.style.left = e.clientX + "px";
            note.style.top = e.clientY + "px";

            document.body.appendChild(note);

            setTimeout(() => {
            note.remove();
            }, 1000);

            lastX = e.clientX;
            lastY = e.clientY;
        }

        });
    }

    // ****** Curseur athlete
    function cursorAthlete() {
        const athleteCursor = document.querySelector(".cursor-follow-athlete");

        if (!athleteCursor) return;

        let lastX = 0;
        let lastY = 0;
        let step = 0;
        let pattern = [1,1,0.5,1,1,0];

        // facteur pour espacer les pas davantage
        const spacingMultiplier = 1.6; // 1 = distance normale, >1 = plus d'espacement

        document.addEventListener("mousemove", (e) => {
            const dx = e.clientX - lastX;
            const dy = e.clientY - lastY;
            const distance = Math.sqrt(dx*dx + dy*dy);

            // distance minimale pour créer un pas
            if (distance > 40) {

                // contrôle du pattern
                let currentPattern = pattern[step % pattern.length];

                if (currentPattern > 0) { // si pas
                    const shoe = document.createElement("div");
                    shoe.classList.add("run-step");

                    // alterner gauche/droite
                    let svgContent = '';
                    if (step % 2 === 0) {
                        shoe.classList.add("left");
                        svgContent = `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="75" height="79" viewBox="0 0 75 79" fill="none">
                        <rect width="66" height="70" transform="translate(0 8.82739) rotate(-7.68621)" fill="url(#pattern0_2013_2)"/>
                        <defs>
                        <pattern id="pattern0_2013_2" patternContentUnits="objectBoundingBox" width="1" height="1">
                        <use xlink:href="#image0_2013_2" transform="matrix(0.00169484 0.000300767 -0.000324917 0.00156887 0.0712133 -0.0851979)"/>
                        </pattern>
                        <image id="image0_2013_2" width="626" height="626" preserveAspectRatio="none" xlink:href="data:image/png;base64,"/>
                        </defs>
                        </svg>`;
                    } else {
                        shoe.classList.add("right");
                        svgContent = `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="81" height="84" viewBox="0 0 81 84" fill="none">
                        <rect width="66" height="70" transform="matrix(-0.970357 0.241676 0.241676 0.970357 64.0436 0)" fill="url(#pattern0_2013_3)"/>
                        <defs>
                        <pattern id="pattern0_2013_3" patternContentUnits="objectBoundingBox" width="1" height="1">
                        <use xlink:href="#image0_2013_3" transform="matrix(0.000794872 0.0014179 -0.00153174 0.000735794 0.730641 -0.174106)"/>
                        </pattern>
                        <image id="image0_2013_3" width="626" height="626" preserveAspectRatio="none" xlink:href="data:image/png;base64,"/>
                        </defs>
                        </svg>`;
                    }

                    shoe.innerHTML = svgContent;

                    // position
                    shoe.style.left = e.clientX + "px";
                    shoe.style.top = e.clientY + "px";

                    document.body.appendChild(shoe);

                    // disparition après 1s
                    setTimeout(() => {
                        shoe.remove();
                    }, 1000);
                }

                // ajuster lastX et lastY pour espacement
                lastX = lastX + dx * currentPattern * spacingMultiplier;
                lastY = lastY + dy * currentPattern * spacingMultiplier;

                step++;
            }
        });
    }

    // ****** Curseur engagement
    function cursorEngage() {
        const flameSVG = `
            <svg viewBox="0 0 20 30" xmlns="http://www.w3.org/2000/svg">
                <path class="flame-orange" d="M10 0 C12 8 18 10 10 30 C2 10 8 8 10 0" fill="var(--color-orange)"/>
                <path class="flame-yellow" d="M10 0 C11 6 15 8 10 28 C5 8 9 6 10 0" fill="var(--color-yellow)" opacity="0.6"/>
                <path class="flame-blue" d="M10 20 C11 22 12 23 10 30 C8 23 9 22 10 20" fill="var(--color-link)" opacity="0.3"/>
            </svg>
        `;

        document.addEventListener("mousemove", (e) => {
            const trail = document.createElement("div");
            trail.classList.add("flame-trail");
            trail.innerHTML = flameSVG;

            trail.style.left = e.clientX + "px";
            trail.style.top = e.clientY + "px";

            document.body.appendChild(trail);

            setTimeout(() => {
                trail.remove();
            }, 800);
        });
    }

    // ****** Curseur technologie
    function cursorTech() {
        const canvas = document.getElementById("cursor-follow-tech")
        const ctx = canvas.getContext("2d")

        canvas.width = window.innerWidth
        canvas.height = window.innerHeight

        // récupérer la couleur CSS
        const rootStyles = getComputedStyle(document.documentElement)
        const baseColor = rootStyles.getPropertyValue('--color-link').trim()

        function hexToRgb(hex){
        hex = hex.replace("#","")

        const bigint = parseInt(hex,16)
        const r = (bigint >> 16) & 255
        const g = (bigint >> 8) & 255
        const b = bigint & 255

        return {r,g,b}
        }

        const rgb = hexToRgb(baseColor)

        let mouse = {x:0,y:0}
        let trails = []
        let lastMoveTime = 0

        window.addEventListener("resize",()=>{
        canvas.width = window.innerWidth
        canvas.height = window.innerHeight
        })

        document.addEventListener("mousemove",(e)=>{

        mouse.x = e.clientX
        mouse.y = e.clientY

        lastMoveTime = Date.now()

        trails.push({
        x:mouse.x,
        y:mouse.y,
        life:1,
        vx:(Math.random()-0.5)*30,
        vy:(Math.random()-0.5)*30
        })

        if(trails.length>50) trails.shift()

        })

        function draw() {
            ctx.clearRect(0,0,canvas.width,canvas.height)

            let now = Date.now()

            for(let i=0;i<trails.length-1;i++){

            let p1 = trails[i]
            let p2 = trails[i+1]

            if(p1.life < 0.02) continue

            // courbure
            let curveX = (p1.x+p2.x)/2 + p1.vx
            let curveY = (p1.y+p2.y)/2 + p1.vy

            ctx.beginPath()
            ctx.moveTo(p1.x,p1.y)

            ctx.quadraticCurveTo(
            curveX,
            curveY,
            p2.x,
            p2.y
            )

            let alpha = p1.life

            // glow externe couleur
            ctx.strokeStyle = `rgba(${rgb.r},${rgb.g},${rgb.b},${alpha})`
            ctx.lineWidth = 4
            ctx.shadowBlur = 25
            ctx.shadowColor = `rgba(${rgb.r},${rgb.g},${rgb.b},1)`
            ctx.stroke()

            // ligne centrale blanche (effet fibre optique)
            ctx.strokeStyle = `rgba(255,255,255,${alpha})`
            ctx.lineWidth = 1.5
            ctx.shadowBlur = 0
            ctx.stroke()

            // node lumineux
            ctx.beginPath()
            ctx.arc(
            curveX,
            curveY,
            4 + Math.sin(now/200)*2,
            0,
            Math.PI*2
            )

            ctx.fillStyle = `rgba(${Math.min(rgb.r+60,255)},${Math.min(rgb.g+60,255)},255,${alpha})`
            ctx.shadowBlur = 40
            ctx.shadowColor = `rgba(${rgb.r},${rgb.g},${rgb.b},1)`
            ctx.fill()

            // particule qui circule
            let t = ((now/600)+i*0.1)%1

            let px = p1.x + (p2.x-p1.x)*t
            let py = p1.y + (p2.y-p1.y)*t

            ctx.beginPath()
            ctx.arc(px,py,2,0,Math.PI*2)

            ctx.fillStyle = `rgba(${rgb.r},${rgb.g},255,${alpha})`
            ctx.shadowBlur = 15
            ctx.fill()

            // fade quand la souris s'arrête
            if(now - lastMoveTime > 120){
            p1.life *= 0.92
            }else{
            p1.life *= 0.97
            }

            }

            requestAnimationFrame(draw)
        }

        draw()
    }

    // ****** Curseur multi
    function cursorMulti() {
        const icons = ["🎵","🏃","💻","🔥","⭐"]

        let lastX = 0
        let lastY = 0

        document.addEventListener("mousemove",(e)=>{

        const dx = e.clientX - lastX
        const dy = e.clientY - lastY
        const distance = Math.sqrt(dx*dx + dy*dy)

            if(distance > 35) {
                const icon = document.createElement("div")
                icon.classList.add("multi-icon")

                icon.textContent = icons[Math.floor(Math.random()*icons.length)]

                icon.style.left = e.clientX + "px"
                icon.style.top = e.clientY + "px"

                document.body.appendChild(icon)

                setTimeout(()=>{
                    icon.remove()
                },1200)

                lastX = e.clientX
                lastY = e.clientY
            }
        })
    }

    // ****** Curseur home
    function cursorHome() {
        const styles = getComputedStyle(document.documentElement)
        const colors = [
            styles.getPropertyValue('--color-link').trim(),
            styles.getPropertyValue('--color-yellow').trim()
        ]

        let lastX = 0
        let lastY = 0

        document.addEventListener("mousemove",(e)=>{
            const dx = e.clientX - lastX
            const dy = e.clientY - lastY
            const distance = Math.sqrt(dx*dx + dy*dy)

            if(distance > 30){

            const star = document.createElement("div")
            star.classList.add("star")

            const color = colors[Math.floor(Math.random()*colors.length)]

            let size = Math.random()*10 + 6

            // étoiles jaunes plus grosses
            if(color === styles.getPropertyValue('--color-yellow').trim()){
            size += 6
            }

            star.innerHTML = `
            <svg width="${size}" height="${size}" viewBox="0 0 24 24">
            <path fill="${color}" d="M12 2 L14.5 9 L22 9 L16 13.5 L18.5 21 L12 16.5 L5.5 21 L8 13.5 L2 9 L9.5 9 Z"/>
            </svg>
            `

            star.style.left = e.clientX + "px"
            star.style.top = e.clientY + "px"

            // ⭐ étoile filante rare
            if(Math.random() < 0.05){

            star.classList.add("shooting")

            // petit scintillement au départ
            star.animate([
            { transform:"translate(-50%, -50%) scale(1.4)", opacity:1 },
            { transform:"translate(-50%, -50%) scale(1)", opacity:1 }
            ],{
            duration:150,
            easing:"ease-out"
            })
            }

            document.body.appendChild(star)

            setTimeout(()=>{
            star.remove()
            },1600)

            lastX = e.clientX
            lastY = e.clientY

            }
        })
    }

    // ****** Initialisation des modules autres pages
    if ($('body').hasClass('page-music')) {
        cursorMusic();
    }
    if ($('body').hasClass('page-athlete')) {
        cursorAthlete();
    }
    if ($('body').hasClass('page-engage')) {
        cursorEngage();
    }
    if ($('body').hasClass('page-tech')) {
        cursorTech();
    }
    if ($('body').hasClass('page-multi')) {
        cursorMulti();
    }
    if ($('body').hasClass('page-home')) {
        cursorHome();
    }

    // ****** Initialisation des modules
    openBurger();
})